// "<skill> - <book>". No table or packet changes; an old client would show the
// marker after a buyer's name only on auction notifications of a book.
static std::string Mt2009PlusBookWho(const std::map<DWORD, TItemTable*>& protos, DWORD vnum, long socket0, const std::string& who)
{
	if (socket0 <= 0 || socket0 > 999)
		return who;
	const auto it = protos.find(vnum);
	if (it == protos.end() || !it->second)
		return who;
	if (it->second->bType != ITEM_SKILLBOOK && it->second->bType != ITEM_SKILLFORGET)
		return who;
	std::string marked = who + fmt::format("#S{}", socket0);
	if (marked.size() > CHARACTER_NAME_MAX_LEN)	// the "who" fields hold a character name
		return who;
	return marked; // MT2009_PLUS_SHOP_BOOK_NOTIFICATION_V1 (who)
}

