// to OFFLINESHOP_DURATION_MAX_MINUTES, and the new duration sent to every core.
bool CClientManager::RecvIkarusShopExtendDuration(const char* data)
{
	const auto& subpack = Decode<ikashop::TSubPacketGDShopExtendDuration>(data);
	auto shop = m_offlineshopShopCache.Get(subpack.owner);
	if (!shop || shop->duration == 0)
		return false;

	const DWORD duration = std::min<DWORD>(OFFLINESHOP_DURATION_MAX_MINUTES, shop->duration + subpack.minutes);
	shop->duration = duration;

	auto query = fmt::format("UPDATE `ikashop_offlineshop` SET `duration` = {} WHERE `owner` = {}", duration, subpack.owner);
	CDBManager::instance().AsyncQuery(query.c_str());

#ifdef ENABLE_IKASHOP_LOGS
	IkarusShopLog(subpack.owner, 0, "SHOP_EXTEND_DURATION", subpack.owner, "");
#endif

	TPacketDGNewIkarusShop pack{};
	pack.bSubHeader = ikashop::SUBHEADER_DG_SHOP_SET_DURATION;

	ikashop::TSubPacketDGShopSetDuration out{};
	out.owner = subpack.owner;
	out.duration = duration;

	for (auto& peer : m_peerList)
	{
		if (peer->GetChannel() != 0)
		{
			peer->EncodeHeader(HEADER_DG_NEW_OFFLINESHOP, 0, sizeof(pack) + sizeof(out));
			peer->Encode(pack);
			peer->Encode(out);
		}
	}
	return true;
}

